            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else if (nums[mid] > target) {
                right = mid - 1;
            } else {
                answer = mid; // 先保存命中，再继续找边界
                if (findLeft) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            }
        }
        return answer;
    }
}

