import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        long[] rowSum = new long[n];
        long[] colSum = new long[m];
        long total = 0;
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                int value = scanner.nextInt();
                rowSum[row] += value;
                colSum[col] += value;
                total += value;
            }
        }
        System.out.println(minDifference(rowSum, colSum, total));
        scanner.close();
    }

    static long minDifference(long[] rowSum, long[] colSum, long total) {
        long result = Long.MAX_VALUE;
        long part = 0;
        // 最后一行之后不是合法切线，两边必须非空
        for (int row = 0; row < rowSum.length - 1; row++) {
            part += rowSum[row];
            result = Math.min(result, Math.abs(part - (total - part)));
        }
        part = 0;
        for (int col = 0; col < colSum.length - 1; col++) {
            part += colSum[col];
            result = Math.min(result, Math.abs(part - (total - part)));
        }
        return result;
    }
}

